from pathlib import Path
import json, html, shutil, os
from xml.sax.saxutils import escape
ROOT=Path(__file__).resolve().parents[1]
site=json.loads((ROOT/'content/site.json').read_text()); articles=json.loads((ROOT/'content/articles.json').read_text())
BASE=os.environ.get('SITE_URL',site['url']).rstrip('/')
OUT=ROOT/'dist'
if OUT.exists(): shutil.rmtree(OUT)
OUT.mkdir(); shutil.copytree(ROOT/'assets',OUT/'assets')
e=html.escape
sections={'news':('The latest, with receipts.','Official announcements and the context that matters.'),'facts':('Facts first. Hype second.','Know what is confirmed, what is unconfirmed, and why.'),'guides':('A better place to start.','Practical launch help and attributed gameplay reports.'),'money':('Make every dollar count.','Reported earning routes and the prerequisites that matter.'),'missions':('Your next move.','A home for clear, carefully checked mission walkthroughs.'),'vehicles':('Find your next ride.','Official bonus vehicles and reported vehicle systems.'),'map':('Get to know Leonida.','Official setting overviews. No speculative coordinates.')}
nav=[('news','News'),('facts','Facts vs rumors'),('guides','Guides'),('money','Money'),('missions','Missions'),('vehicles','Vehicles'),('map','Map'),('faq','FAQ')]
paths=[]
def card(a):
 return f'''<a class="card" data-search="{e(' '.join(a.get('body',[]) + a.get('keywords',[])), quote=True)}" data-category="{a['category']}" data-status="{a['status']}" href="/articles/{a['slug']}/"><div class="card-top"><span class="tag {a['status'].lower().replace(' ','-')}">{a['status']}</span><span class="arrow">↗</span></div><p class="eyebrow">{a['category']}</p><h3>{e(a['title'])}</h3><p>{e(a['summary'])}</p><span class="card-foot">READ THE STORY <span>→</span></span></a>'''
def cards(items): return '<div class="cards">'+''.join(map(card,items))+'</div>'
def official_news():
 data=json.loads((ROOT/'content/official-news.json').read_text())
 items=''.join(f'<a class="card" href="{e(item["url"])}"><p class="eyebrow">OFFICIAL SOURCE · ROCKSTAR GAMES</p><h3>{e(item["title"])}</h3><p>{e(item.get("published") or "Publication date not provided")}</p><span class="card-foot">READ ON ROCKSTAR ↗</span></a>' for item in data['items'])
 return f'<section><p class="eyebrow">FROM THE PUBLISHER</p><h2>Official GTA VI news</h2><p>Headlines linked directly from Rockstar’s GTA VI page. Source articles open on Rockstar; these are not independently written guides.</p><p class="byline">Feed last changed: {e(data["updated"])} · Coverage is limited to Rockstar’s featured links.</p><div class="cards">{items}</div></section>'
def page(path,title,desc,body,active='',article=None):
 canonical=BASE+path; paths.append(path)
 if path in ['/', '/news/']: body+=official_news()
 ld={'@context':'https://schema.org','@type':'WebSite' if path=='/' else 'WebPage','name':title,'url':canonical,'description':desc}
 if article: ld.update({'@type':'Article','headline':title,'dateModified':article.get('updated',site['checked']),'author':{'@type':'Organization','name':site['name']}})
 s=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | GTA6Answers.gg</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:url" content="{canonical}"><meta name="twitter:card" content="summary"><meta name="theme-color" content="#11151b"><link rel="icon" href="/assets/icon.svg"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{json.dumps(ld)}</script><script defer src="/assets/app.js"></script></head><body><a class="skip" href="#main">Skip to content</a><div class="edition"><span>THE LEONIDA FIELD NOTES</span><span>LAUNCH COVERAGE · CHECKED NOV 18, 2026</span></div><header><a class="brand" href="/" aria-label="GTA6Answers home">GTA<span>6</span>ANSWERS<small>.GG</small></a><button class="menu" aria-expanded="false" aria-controls="nav">Menu ☰</button><nav id="nav" aria-label="Main navigation">{''.join(f'<a href="/{key}/" '+('aria-current="page"' if key==active else '')+f'>{label}</a>' for key,label in nav)}<a class="search-link" href="/search/">Search ↗</a></nav></header><main id="main">{body}</main><section class="trust"><div><span class="eyebrow">OUR EDITORIAL PROMISE</span><h2>Good answers have sources.</h2></div><p>Official information is labeled. Unverified claims stay unverified. Reported gameplay is attributed to its source. We never imply hands-on testing we have not done.</p><a href="/editorial/">How we work →</a></section><footer><a class="brand" href="/">GTA<span>6</span>ANSWERS<small>.GG</small></a><p>An independent fan resource. Not affiliated with or endorsed by Rockstar Games or Take-Two Interactive. Grand Theft Auto and related marks belong to their owners.</p><div><a href="/editorial/">Editorial & sources</a><a href="/privacy/">Privacy</a><a href="/faq/">FAQ</a><a href="/sitemap.xml">Sitemap</a></div><small>© 2026 GTA6Answers.gg · Original illustration, not game footage.</small></footer></body></html>'''
 target=OUT/(path.strip('/')+'/index.html' if path!='/' else 'index.html'); target.parent.mkdir(parents=True,exist_ok=True); target.write_text(s)
page('/','GTA 6 news, facts and guides','Independent GTA VI launch news, sourced facts, practical help and attributed gameplay guides.',f'''<section class="hero"><img src="/assets/coast.svg" alt="Original illustration of a coastal skyline at sunset"><div class="hero-shade"></div><div class="hero-copy"><p class="eyebrow">WELCOME TO YOUR NEXT OBSESSION</p><h1>Big city.<br>Better answers.</h1><p>Your independent guide to GTA VI.<br>Less speculation. More substance.</p><div class="actions"><a class="button" href="/facts/">Explore verified facts ↗</a><a class="button ghost" href="/guides/">Find a guide →</a></div></div><span class="art-label">LEONIDA, REIMAGINED · ORIGINAL ARTWORK</span></section><div class="status-strip"><span class="status-dot">●</span><strong>Regional release: Nov 19, midnight local time</strong><span>PS5 · Xbox Series X|S</span><a href="/articles/release-date-platforms/">Source & status ↗</a></div><section><div class="section-head"><div><p class="eyebrow">THE BRIEFING</p><h2>Stay ahead of the noise.</h2></div><a href="/news/">All news →</a></div>{cards(articles[:3])}</section><section class="explore"><div><p class="eyebrow">PICK YOUR NEXT STOP</p><h2>A whole new world.<br>One place to start.</h2><p>Explore the essentials for launch.<br>Build your knowledge as Leonida opens up.</p></div><div class="topic-grid">{''.join(f'<a href="/{k}/"><span>0{i+1}</span><h3>{label}</h3><b>↗</b></a>' for i,(k,label) in enumerate(nav[2:7]))}<a href="/search/"><span>06</span><h3>All answers</h3><b>↗</b></a></div></section><section><div class="section-head"><div><p class="eyebrow">KNOW THE DIFFERENCE</p><h2>Confirmed or just conversation?</h2></div><a href="/facts/">Check the facts →</a></div>{cards([a for a in articles if a['slug'] in ('release-date-platforms','pc-release-rumors','new-zealand-early-access')])}</section>''')
for k,(title,desc) in sections.items():
 items=[a for a in articles if a['category']==k]
 if k=='facts': items=[a for a in articles if a['status'] in ('Verified','Unconfirmed')]
 notice='<div class="notice">Evidence matters: Verified means official-source support; Reported means attributed published reporting, not our own testing. Open an article for its source and spoiler notice.</div>' if k in ['guides','money','missions','vehicles'] else ''
 page('/'+k+'/',title,desc,f'<section><p class="eyebrow">FIELD NOTES / {k.upper()}</p><h1>{title}</h1><p class="intro">{desc}</p>{notice}{cards(items)}</section>',k)
for a in articles:
 source=site['sources'].get(a.get('source'))
 citations=f'<aside class="source"><h2>Source & review</h2><a href="{e(source["url"])}">{e(source["name"])} ↗</a><p>Reviewed {e(a.get("updated",site["checked"]))}. See the source for full context and later corrections.</p></aside>' if source else '<aside class="source"><h2>Verification status</h2><p>Untested editorial preparation. No hands-on gameplay claims.</p></aside>'
 label={'Verified':'Supported by the linked official source. This is not a claim of independent gameplay testing.','Reported':'Attributed published reporting. GTA6Answers has not independently reproduced these gameplay results.','Editorial':'Original editorial advice, not a claim about a tested gameplay mechanic.','Unconfirmed':'The claim is not established by the sources checked.','Pre-release':'Untested sample coverage.'}[a['status']]
 content=''.join(f'<p>{e(p)}</p>' for p in a['body'])
 for block in a.get('sections',[]):
  content+=f'<h2>{e(block["heading"])}</h2>'
  if block.get('text'): content+=f'<p>{e(block["text"])}</p>'
  if block.get('items'): content+='<ul>'+''.join(f'<li>{e(item)}</li>' for item in block['items'])+'</ul>'
 spoiler=a.get('spoiler','No story outcomes.')
 if spoiler not in ('No story outcomes.','Official character backstories only.'):
  content=f'<details class="spoiler"><summary>Reveal guide — {e(spoiler)}</summary>{content}</details>'
 related=[b for b in articles if b!=a and b['category']==a['category']][:3]
 if not related: related=[b for b in articles if b!=a][:2]
 body=f'<section class="article"><a href="/{a["category"]}/">← Back to {a["category"]}</a><p class="eyebrow">{a["category"]} / {a["status"]}</p><h1>{e(a["title"])}</h1><p class="intro">{e(a["summary"])}</p><p class="byline">GTA6Answers editorial · Updated {e(a.get("updated",site["checked"]))}</p><div class="notice"><strong>{e(a["status"])}</strong> — {label}<br>Spoilers: {e(spoiler)}</div>'+content+citations+'<h2>Keep exploring</h2>'+cards(related)+'</section>'
 page('/articles/'+a['slug']+'/',a['title'],a['summary'],body,a['category'],a)

faq=[('When is GTA VI scheduled to release?','The official listing checked November 18, 2026 names November 19, 2026. See our release article and its primary source for the dated status.'),('Which platforms are listed?','PlayStation 5 and Xbox Series X|S. The checked official listing does not announce a PC release date.'),('Who tested the gameplay guides?','Our Reported guides attribute published hands-on coverage to named outlets. GTA6Answers has not independently tested those results. Each article carries a source and spoiler label.'),('Is this an official Rockstar website?','No. GTA6Answers.gg is an independent fan project with no Rockstar or Take-Two affiliation.'),('Does switching to New Zealand guarantee early access?','We have not verified that claim. Official regional release timing is not proof that an account-switch method works.'),('Is there a complete interactive map?','Not here yet. Our location pages describe the official setting. We do not invent map geometry or collectible coordinates.')]
page('/faq/','Frequently asked questions','Clear answers about release status, platforms and our editorial coverage.','<section class="article"><p class="eyebrow">THE ESSENTIALS</p><h1>Good questions.<br>Clear answers.</h1>'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)+'<p><a href="/editorial/">See sources and our editorial policy →</a></p></section>','faq')
page('/search/','Search the field notes','Search GTA VI news, guides, money, missions, vehicles and locations.','''<section><p class="eyebrow">FIND YOUR ANSWER</p><h1>The field notes, at your fingertips.</h1><form action="/search/" class="filters"><label>Search articles<input id="query" name="q" type="search" placeholder="Try platforms, money or Vice City"></label><label>Section<select id="category"><option value="">All sections</option>'''+''.join(f'<option value="{k}">{label}</option>' for k,label in nav if k!='faq')+'''</select></label><label>Evidence<select id="status"><option value="">All statuses</option><option>Verified</option><option>Reported</option><option>Editorial</option><option>Pre-release</option><option>Unconfirmed</option></select></label><button class="button" type="submit">Search</button></form><p id="result-count" role="status" aria-live="polite"></p>'''+cards(articles)+'''<p id="empty" hidden>No matching articles. Try a broader search or clear the filters.</p><noscript><p>Enable JavaScript for live filtering, or browse all articles below.</p></noscript></section>''')
page('/editorial/','Editorial policy and sources','How GTA6Answers verifies claims and labels pre-release content.','<section class="article"><p class="eyebrow">TRANSPARENCY</p><h1>Every claim earns its place.</h1><h2>Evidence labels</h2><p><strong>Verified</strong> means supported by a linked primary source as of the review date. <strong>Unconfirmed</strong> means the claim is not established by the sources we checked. <strong>Reported</strong> identifies attributed published reporting, not independent testing by this site. <strong>Editorial</strong> identifies our practical advice. <strong>Pre-release</strong> is reserved for untested sample coverage plans.</p><h2>Sources</h2><ul>'+''.join(f'<li><a href="{v["url"]}">{v["name"]}</a> — checked {site["checked"]}</li>' for v in site['sources'].values())+'</ul><h2>Testing and corrections</h2><p>Before labeling a guide independently tested, record platform, game version, prerequisites, reproducible steps and results. Attributed summaries may be published as Reported before our own testing. Correct errors in the source content, update the review date and explain material changes in the article. This initial edition has no hands-on testing.</p><h2>Spoilers and rumors</h2><p>We do not reproduce leaks or treat speculation as fact. Gameplay articles carry spoiler labels; progression details are behind an expandable disclosure. Release status is a dated snapshot and does not automatically change at midnight.</p><h2>Independence</h2><p>This is a fan website. There is no affiliation with Rockstar Games or Take-Two, and no paid placement or affiliate links in this edition. Illustrations are original decorative art.</p></section>')
page('/privacy/','Privacy','Privacy information for this static website.','<section class="article"><h1>A quieter kind of website.</h1><p>This edition uses no analytics, advertising scripts, cookies, account system or remote fonts. Search runs in your browser. Search terms may appear in your browser history as URL parameters.</p><p>Your hosting provider may retain ordinary request logs, including IP addresses and visited URLs. External source links take you to sites with their own privacy policies. The site operator should update this policy when selecting a host or adding services.</p></section>')
page('/404/','Page not found','Return to GTA6Answers and find the page you need.','<section><p class="eyebrow">WRONG TURN</p><h1>This street ends here.</h1><p>Try the article library or return to the homepage.</p><a class="button" href="/search/">Find an answer →</a></section>')
shutil.copyfile(OUT/'404/index.html',OUT/'404.html')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{escape(BASE+p)}</loc><lastmod>{site["checked"]}</lastmod></url>' for p in paths if p!='/404/')+'</urlset>')
(OUT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n')
print(f'Built {len(paths)} pages in {OUT}')
